import { SOLAR_ICONS, type IconName } from "@/lib/icons/solar-data";

export type { IconName };

// Solar Icons, same set as the Flutter app: linear = SolarIconsOutline, bold (filled) = SolarIconsBold.
// Bodies are generated by scripts/gen-icons.mjs; they paint with currentColor.
export function Icon({
  name,
  className = "size-6",
  filled = false,
}: {
  name: IconName;
  className?: string;
  filled?: boolean;
}) {
  const body = SOLAR_ICONS[name][filled ? "bold" : "linear"];
  return (
    <svg
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
}
